func greet(name) {
    println("Hello, " + name + "!");
}

greet("Alice");
greet("Bob");

func factorial(n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

let result := factorial(5);
println(result);

func is_even(n) {
    return n % 2 == 0;
}

let result := is_even(4);
println(result);

func average(a, b) {
    return (a + b) / 2;
}

let avg := average(10, 20);
println(avg);

func double(n) {
    return n * 2;
}

func square(n) {
    return n * n;
}

let x := 5;
println(double(x));
println(square(x));
